import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"40、【解】 坎下震上","description":"橫渠易說 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"橫渠易說 - 40、【解】 坎下震上"},"headers":[],"relativePath":"classics/hengqu/042.md","filePath":"classics/hengqu/042.md"}'),l={name:"classics/hengqu/042.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><h3 id="彖曰-解-險以動-動而免乎險-解。-解利西南-往得眾也-其來複吉-乃得中也-有攸往夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼-解之時大矣哉" tabindex="-1">彖曰：解，險以動，動而免乎險，解。“解利西南”，往得眾也，“其來複吉”，乃得中也，“有攸往夙吉”，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼，解之時大矣哉! <a class="header-anchor" href="#彖曰-解-險以動-動而免乎險-解。-解利西南-往得眾也-其來複吉-乃得中也-有攸往夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼-解之時大矣哉" aria-label="Permalink to “彖曰：解，險以動，動而免乎險，解。“解利西南”，往得眾也，“其來複吉”，乃得中也，“有攸往夙吉”，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼，解之時大矣哉!”">​</a></h3><h3 id="象曰-雷雨作-解-君子以赦過宥罪。" tabindex="-1">象曰：雷雨作，解，君子以赦過宥罪。 <a class="header-anchor" href="#象曰-雷雨作-解-君子以赦過宥罪。" aria-label="Permalink to “象曰：雷雨作，解，君子以赦過宥罪。”">​</a></h3><p>難免人患散，則得眾者吉，往而不返，則生他變。有所往而不速，將後於時也，故無所往則靜吉，有所往則速吉。</p><h3 id="初六-無咎。-象曰-剛柔之際-義無咎也。" tabindex="-1">初六，無咎。 象曰：剛柔之際，義無咎也。 <a class="header-anchor" href="#初六-無咎。-象曰-剛柔之際-義無咎也。" aria-label="Permalink to “初六，無咎。 象曰：剛柔之際，義無咎也。”">​</a></h3><p>險難方解，未護所安，近比於二，非其咎也。</p><h3 id="九二-田護三狐-得黃矢-貞吉。-象曰-九二貞吉-得中道也。" tabindex="-1">九二，田護三狐，得黃矢，貞吉。 象曰：九二貞吉，得中道也。 <a class="header-anchor" href="#九二-田護三狐-得黃矢-貞吉。-象曰-九二貞吉-得中道也。" aria-label="Permalink to “九二，田護三狐，得黃矢，貞吉。 象曰：九二貞吉，得中道也。”">​</a></h3><p>險亂方解，不正自疑之陰，皆自歸附而順聽也，故曰“田護三狐”。不以三狐自累，上合於五，則得黃矢之象也。</p><h3 id="六三-負且乘-致寇至-貞吝。-象曰-負且乘-亦可醜也。自我致戎-又誰咎也" tabindex="-1">六三，負且乘，致寇至，貞吝。 象曰：“負且乘”，亦可醜也。自我致戎，又誰咎也! <a class="header-anchor" href="#六三-負且乘-致寇至-貞吝。-象曰-負且乘-亦可醜也。自我致戎-又誰咎也" aria-label="Permalink to “六三，負且乘，致寇至，貞吝。 象曰：“負且乘”，亦可醜也。自我致戎，又誰咎也!”">​</a></h3><p>不正而近比二剛，不能致一，故有小人負乘之象，貪以致寇也。</p><h3 id="九四-解而拇-朋至斯孚。-象曰-解而拇-未當位也。" tabindex="-1">九四，解而拇，朋至斯孚。 象曰：“解而拇”，未當位也。 <a class="header-anchor" href="#九四-解而拇-朋至斯孚。-象曰-解而拇-未當位也。" aria-label="Permalink to “九四，解而拇，朋至斯孚。 象曰：“解而拇”，未當位也。”">​</a></h3><p>位不當則所履者邪，故失位之陰因得駢附。險亂即解，解之則朋信。當一作正。</p><h3 id="六五-君子惟有解-吉。有孚於小人。-象曰-君子有解-小人退也。" tabindex="-1">六五，君子惟有解，吉。有孚於小人。 象曰：君子有解，小人退也。 <a class="header-anchor" href="#六五-君子惟有解-吉。有孚於小人。-象曰-君子有解-小人退也。" aria-label="Permalink to “六五，君子惟有解，吉。有孚於小人。 象曰：君子有解，小人退也。”">​</a></h3><p>君子道亨，則邪類之退必矣。</p><h3 id="上六-公用射隼於高墉之上-護之無不利。-象曰-公用射隼-以解悖也。" tabindex="-1">上六，公用射隼於高墉之上，護之無不利。 象曰：“公用射隼”，以解悖也。 <a class="header-anchor" href="#上六-公用射隼於高墉之上-護之無不利。-象曰-公用射隼-以解悖也。" aria-label="Permalink to “上六，公用射隼於高墉之上，護之無不利。 象曰：“公用射隼”，以解悖也。”">​</a></h3><p>忘義而貪，故以喻隼。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
